package com.johnny.hotel.financeexpense;import jakarta.validation.constraints.*;import java.math.*;import java.time.*;public final class ExpenseCommands{private ExpenseCommands(){}public record Create(@NotNull @DecimalMin("0.01") @Digits(integer=10,fraction=2)BigDecimal amount,@NotBlank @Pattern(regexp="[A-Za-z]{3}")String currency,@NotNull ExpenseCategory category,@NotBlank @Size(max=500)String description,@Size(max=100)String referenceNo,@NotNull LocalDate expenseDate,LocalDate serviceDate,String relatedType,Long relatedId,Long employeeUserId,@NotBlank @Size(min=8,max=100)String requestKey){}public record Action(@NotBlank @Size(min=8,max=100)String requestKey,@Size(max=500)String reason){}public record Pay(@NotBlank @Size(min=8,max=100)String requestKey,@NotBlank @Size(max=30)String paymentMethod,@Size(max=100)String externalReference){} }
